import{_ as t,o as r,c as n,a2 as p}from"./chunks/framework.B2QVIpOM.js";const i=JSON.parse('{"title":"保良局颜宝铃书院 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-6153994b","school_zh":"保良局颜宝铃书院","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"保良局颜宝铃书院 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-NPL-U","NPL-S1-UNDATED-GROUP"],"rounds":["unknown","r2"]},"headers":[],"relativePath":"reports/school-6153994b/s1/unknown-interview.md","filePath":"reports/school-6153994b/s1/unknown-interview.md"}'),e={name:"reports/school-6153994b/s1/unknown-interview.md"};function s(a,o,l,g,c,u){return r(),n("div",null,[...o[0]||(o[0]=[p('<h1 id="保良局颜宝铃书院-·-年份未注明-·-中一-·-面试" tabindex="-1">保良局颜宝铃书院 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#保良局颜宝铃书院-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;保良局颜宝铃书院 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-6153994b">← 返回保良局颜宝铃书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-npl-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-npl-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-npl-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读、理解与快速口答</strong></p><p>自我介绍，朗读文章或词语、完成理解及不供词填充；部分题用iPad显示，内容包括语法、时态、词形、冠词、介词。有约3分钟作答的环节，亦有口答试卷和连续快速提问，考生感觉节奏很急。</p></blockquote><blockquote><p><strong>语文：</strong> 中文、普通话</p><p><strong>词句、朗读与理解</strong></p><p>中文自我介绍、口答试卷、不供词填充及成语；iPad题包括辨词、句义和段义理解、供词填充。普通话朗读文章或报纸并做理解，部分环节约3分钟，也有快速连续提問。</p></blockquote><blockquote><p><strong>数学：</strong> 英语；另有中文题</p><p><strong>限时运算</strong></p><p>口答计算题，混合加减乘除及含π的心算。一组约3分钟；另有中文方程及乘法题，每题约30秒。</p></blockquote><blockquote><p><strong>个人及家庭面谈：</strong> 中文为主，部分普通话及英语</p><p><strong>生活情境与自我安排</strong></p><p>家附近若建图书馆、游乐场或港铁站会选哪项及原因？父母工作疲倦回家会给什么惊喜，母亲生日准备什么礼物？如何放松、是否安排时间表及如何落实？为什么报读，怎样评价上次面试，应否取消暑假作业？</p><p><strong>指定语言问题</strong></p><p>普通话：若在街上遇到特首想问什么。英语：是否有兄弟姊妹在校、想加入哪个学会、如何到校、父母从事什么工作。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 中文、英语</p><p><strong>毕业、义工与送别</strong></p><p>讨论小六毕业日流程，或在3.5分钟内提出至少5种义工活动建议；也问父母回家会做什么、朋友移民前一天会带他去香港哪里。</p></blockquote><blockquote><p><strong>小组任务：</strong> 粤语、普通话、英语均可沟通</p><p><strong>运送乒乓球</strong></p><p>4人一组，用1个纸杯、2条橡皮筋及4条绳子把球从A桌送到B桌。另一组工具有纸杯、橡皮圈和万字夹，不可用手碰杯；也有不得用手碰球的版本。另有看图说故事。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>报读原因与居家表现</strong></p><p>为什么希望孩子入读，孩子在家里的表现怎样。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>双语面谈：</strong> 英语、中文及普通话</p><p><strong>再次问答</strong></p><p>有学生明确提到第二次面试为英语和中文／普通话问答，未进一步记下对应题目。</p></blockquote><h2 id="record-npl-s1-undated-group" tabindex="-1">资料来源：颜宝玲书院中一入学考情【仅有面试（占分10_）】.pdf；颜宝玲面試題.pdf <a class="header-anchor" href="#record-npl-s1-undated-group" aria-label="Permalink to &quot;资料来源：颜宝玲书院中一入学考情【仅有面试（占分10_）】.pdf；颜宝玲面試題.pdf {#record-npl-s1-undated-group}&quot;">​</a></h2><p><strong>资料类型：</strong> 历史反馈及题目整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>英文填写资料</strong></p><p>开始时用英文填写基本资料，需要分清first name和last name。历史反馈包含一次面试内的中英文讨论，未考数学。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>四人讨论｜约5分钟</strong></p><p>四人一组，准备约1分钟、讨论约4分钟，香港本地考生也使用普通话。题目包括：</p><ul><li>哭泣是不是软弱的表现？谈谈看法。</li><li>朋友即将移民，离港前一天会带他去香港哪个地方？</li></ul></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>校园报纸｜约5分钟</strong></p><p>四人一组，准备约1分钟、讨论约4分钟：怎样为校园报纸命名，为什么？报纸可以包含健康、学校、体育、学习等哪些内容？由谁写稿？如何招募成员、征集来稿，是否只使用电邮信箱？多久出版一次，为什么？还有什么补充？</p><p><strong>毕业日义工｜另一历史题目</strong></p><p>讨论小学六年级毕业日活动安排，按题目要求在3.5分钟内提出至少5种义工工作建议。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>同组互动体验</strong></p><p>一位家长回忆，孩子所在组轮流发言，不用抢话；家长也认为遇到更活跃的小组时，应主动把握表达机会。此为个人经历及建议。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>情境与选择题</strong></p><p>如果政府拟在家附近建图书馆、游乐场或港铁站，你会选择哪一种，为什么？父母工作疲累时，怎样给他们惊喜？妈妈生日送什么礼物？怎样放松，会给朋友什么建议？如何安排时间？为什么选这所学校？见到行政长官会问什么？</p><p><strong>格言讨论</strong></p><p>从“少壮不努力，老大徒伤悲”、不要因善恶之事细小而忽视其影响、“三人行必有我师”等语句中，选出对青少年最有启发的一项并解释。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我介绍与校园适应</strong></p><p>自我介绍，谈一项希望改善的地方；是否听得懂粤语、会怎样学习；来港多久、如何适应及面对困难；怎样安排时间；学校哪里最吸引你；团队角色与风纪职责；是否有兄弟姐妹就读；希望参加什么社团；怎样上学；父母从事什么工作。</p></blockquote>',28)])])}const b=t(e,[["render",s]]);export{i as __pageData,b as default};
